/**
 * Creates procedural slash arc, lightning bolt, and instanced ribbon trail pools.
 */
export function createTrailsSystem({ mode, THREE, scene, is2D, maxSlashes, maxBolts, maxTrails, trailNodes, atlasRegions, prng, }?: {
    mode?: string | undefined;
    THREE?: any;
    scene?: any;
    is2D?: boolean | undefined;
    maxSlashes?: number | undefined;
    maxBolts?: number | undefined;
    maxTrails?: number | undefined;
    trailNodes?: number | undefined;
    atlasRegions?: Record<string, readonly number[]> | null | undefined;
    prng?: {
        nextFloat(): number;
        range(min: any, max: any): any;
        reset(newSeed?: number): void;
    } | undefined;
}): {
    slashArc: (opts?: {}) => void;
    lightningBolt: (opts?: {}) => void;
    setTrailTexture: (texture: object | null, uvRect?: readonly number[] | undefined) => void;
    setDepthTexture: (depthTexture: any, { near, far, width, height, softFade }?: {
        near?: number | undefined;
        far?: number | undefined;
        width?: number | undefined;
        height?: number | undefined;
        softFade?: number | undefined;
    }) => void;
    setTrailPoints: (trackId: any, px: any, py: any, pz: any, indices: any, startIdx: any, endIdx: any) => void;
    setAtlasRegions: (regions: Record<string, readonly number[]> | null) => void;
    setTrailWidthScale: (trackId: any, scale?: number) => void;
    allocTrail: (colorOrOpts?: number | object, width?: number | undefined) => number;
    pushTrailPoint: (trackId: any, x: any, y: any, z?: number, timeOverride?: undefined) => void;
    updateTrailHead: (trackId: any, x: any, y: any, z?: number, timeOverride?: undefined) => void;
    freeTrail: (trackId: any) => void;
    update: (visualDt: any) => void;
    renderCanvas2D: (ctx: any, camera: any, viewWidth: any, viewHeight: any) => void;
    reset: () => void;
    dispose: () => void;
    getTime: () => number;
    getStats(): {
        slashCap: number;
        boltCap: number;
        trailCap: number;
        trailNodes: number;
        activeTrails: number;
    };
};
export const SLASH_VERTEX_GLSL: "\nprecision highp float;\n\nattribute vec3 position;\nattribute vec2 uv;\nattribute vec4 aSlashP0; // x, y, z, spawnTime\nattribute vec4 aSlashP1; // yawRad, sweepRad, radius, duration\nattribute vec4 aSlashP2; // rgb24, innerRatio, flipDir, thickness\n\nuniform mat4 projectionMatrix;\nuniform mat4 modelViewMatrix;\nuniform float uTime;\nuniform float uIs2D;\n\nvarying vec2 vUv;\nvarying vec3 vColor;\nvarying float vProgress;\nvarying float vSweep;\nvarying float vInner;\nvarying float vFlip;\nvarying float vThickness;\n\nvec3 unpackRgb24(float v) {\n  float r = floor(v / 65536.0);\n  float rem = v - r * 65536.0;\n  float g = floor(rem / 256.0);\n  float b = rem - g * 256.0;\n  return vec3(r, g, b) / 255.0;\n}\n\nvoid main() {\n  float age = uTime - aSlashP0.w;\n  float dur = aSlashP1.w;\n  if (dur <= 0.0 || age < 0.0 || age >= dur) {\n    gl_Position = vec4(2.0, 2.0, 2.0, 1.0);\n    return;\n  }\n\n  vProgress = age / dur;\n  vUv = uv * 2.0 - 1.0;\n  vColor = unpackRgb24(aSlashP2.x);\n  vSweep = aSlashP1.y;\n  vInner = aSlashP2.y;\n  vFlip = aSlashP2.z;\n  vThickness = aSlashP2.w;\n\n  float yaw = aSlashP1.x;\n  float radius = aSlashP1.z;\n  float c = cos(yaw);\n  float s = sin(yaw);\n  vec2 local = position.xy * (radius * 2.0);\n\n  vec3 worldPos;\n  if (uIs2D > 0.5) {\n    worldPos = vec3(\n      aSlashP0.x + local.x * c - local.y * s,\n      aSlashP0.y + local.x * s + local.y * c,\n      aSlashP0.z\n    );\n  } else {\n    worldPos = vec3(\n      aSlashP0.x + local.x * c - local.y * s,\n      aSlashP0.y,\n      aSlashP0.z + local.x * s + local.y * c\n    );\n  }\n  gl_Position = projectionMatrix * modelViewMatrix * vec4(worldPos, 1.0);\n}\n";
export const SLASH_FRAGMENT_GLSL: "\nprecision highp float;\n\nvarying vec2 vUv;\nvarying vec3 vColor;\nvarying float vProgress;\nvarying float vSweep;\nvarying float vInner;\nvarying float vFlip;\nvarying float vThickness;\n\nvoid main() {\n  float r = length(vUv);\n  if (r > 1.0 || r < vInner * 0.7) discard;\n\n  float ang = atan(vUv.y, vUv.x);\n  float normAng = clamp((ang + vSweep * 0.5) / max(0.01, vSweep), 0.0, 1.0);\n  if (vFlip > 0.5) normAng = 1.0 - normAng;\n\n  float u = 1.0 - vProgress;\n  float head = 1.0 - u * u * u * u * u;\n  float tail = smoothstep(0.15, 1.0, vProgress) * 0.92;\n  if (normAng > head || normAng < tail) discard;\n\n  float arcT = (normAng - tail) / max(0.001, head - tail);\n  float bandWidth = (1.0 - vInner) * mix(0.25, 1.0, arcT) * vThickness;\n  float midR = mix(vInner + bandWidth * 0.5, 0.96 - bandWidth * 0.5, arcT);\n  float radial = 1.0 - smoothstep(bandWidth * 0.35, bandWidth * 0.65, abs(r - midR));\n\n  float streak = 0.78 + 0.22 * sin(r * 38.0 + normAng * 12.0);\n  float edgeHot = smoothstep(midR, 0.98, r) * arcT;\n  float alpha = radial * streak * (1.0 - vProgress * vProgress) * smoothstep(0.0, 0.2, arcT);\n  if (alpha < 0.01) discard;\n\n  vec3 col = mix(vColor, vec3(1.0), edgeHot * 0.75);\n  gl_FragColor = vec4(col, alpha);\n}\n";
export const LIGHTNING_VERTEX_GLSL: "\nprecision highp float;\n\nattribute vec3 position; // x in [0..1] along bolt, y in [-0.5..0.5] across width\nattribute vec4 aBoltP0;  // x0, y0, z0, spawnTime\nattribute vec4 aBoltP1;  // x1, y1, z1, duration\nattribute vec4 aBoltP2;  // rgb24, thickness, seed, jitterAmp\n\nuniform mat4 projectionMatrix;\nuniform mat4 modelViewMatrix;\nuniform float uTime;\nuniform float uIs2D;\n\nvarying vec2 vBoltUv;\nvarying vec3 vColor;\nvarying float vAlpha;\n\nvec3 unpackRgb24(float v) {\n  float r = floor(v / 65536.0);\n  float rem = v - r * 65536.0;\n  float g = floor(rem / 256.0);\n  float b = rem - g * 256.0;\n  return vec3(r, g, b) / 255.0;\n}\n\nfloat hash11(float p) {\n  p = fract(p * 0.1031);\n  p *= p + 33.33;\n  p *= p + p;\n  return fract(p);\n}\n\nvoid main() {\n  float age = uTime - aBoltP0.w;\n  float dur = aBoltP1.w;\n  if (dur <= 0.0 || age < 0.0 || age >= dur) {\n    gl_Position = vec4(2.0, 2.0, 2.0, 1.0);\n    return;\n  }\n\n  float t = age / dur;\n  vAlpha = 1.0 - t * t;\n  vBoltUv = vec2(position.x, position.y + 0.5);\n  vColor = unpackRgb24(aBoltP2.x);\n\n  vec3 a = aBoltP0.xyz;\n  vec3 b = aBoltP1.xyz;\n  vec3 seg = b - a;\n  float len = max(0.001, length(seg));\n  vec3 dir = seg / len;\n\n  float stepFrame = floor(uTime * 35.0) + aBoltP2.z * 97.0;\n  float segId = floor(position.x * 16.0);\n  float n1 = hash11(segId * 13.7 + stepFrame * 7.3) * 2.0 - 1.0;\n  float n2 = hash11(segId * 29.1 + stepFrame * 11.9) * 2.0 - 1.0;\n  float env = sin(position.x * 3.14159265);\n  float amp = aBoltP2.w * env * min(1.0, len * 0.35);\n\n  vec3 side = (uIs2D > 0.5)\n    ? vec3(-dir.y, dir.x, 0.0)\n    : normalize(cross(dir, vec3(0.0, 1.0, 0.001)));\n  vec3 up = (uIs2D > 0.5)\n    ? vec3(0.0, 0.0, 1.0)\n    : cross(side, dir);\n\n  vec3 center = mix(a, b, position.x) + side * (n1 * amp) + up * (n2 * amp * 0.45);\n  vec3 worldPos = center + side * (position.y * aBoltP2.y * (1.0 - t * 0.35));\n  gl_Position = projectionMatrix * modelViewMatrix * vec4(worldPos, 1.0);\n}\n";
export const LIGHTNING_FRAGMENT_GLSL: "\nprecision highp float;\n\nvarying vec2 vBoltUv;\nvarying vec3 vColor;\nvarying float vAlpha;\n\nvoid main() {\n  float d = abs(vBoltUv.y - 0.5) * 2.0;\n  float core = exp(-7.5 * d * d);\n  float glow = exp(-2.4 * d * d) * 0.7;\n  float alpha = (core + glow) * vAlpha;\n  if (alpha < 0.01) discard;\n  vec3 col = mix(vColor, vec3(1.0), core * 0.85);\n  gl_FragColor = vec4(col, alpha);\n}\n";
export const RIBBON_VERTEX_GLSL: "\nprecision highp float;\n\nattribute vec3 position; // x in [-0.5..0.5] along segment, y in [-0.5..0.5] across width\nattribute vec4 aSegA;    // x0, y0, z0, t0 (head-to-tail [0..1])\nattribute vec4 aSegB;    // x1, y1, z1, t1\nattribute vec4 aSegMeta; // rgb24, width, alpha0, alpha1\nattribute vec4 aSegExtra; // endRgb24, widthScale0, widthScale1, hdr\nattribute vec4 aSegUvRect; // u0, v0, u1, v1 (atlas UV override, z<=x means use uTrailUvRect)\n\nuniform mat4 projectionMatrix;\nuniform mat4 modelViewMatrix;\nuniform float uIs2D;\n\nvarying vec2 vUv;\nvarying vec3 vColor;\nvarying float vAlpha;\nvarying float vHdr;\nvarying vec4 vUvRect;\n\nvec3 unpackRgb24(float v) {\n  float r = floor(v / 65536.0);\n  float rem = v - r * 65536.0;\n  float g = floor(rem / 256.0);\n  float b = rem - g * 256.0;\n  return vec3(r, g, b) / 255.0;\n}\n\nvoid main() {\n  float w = aSegMeta.y;\n  if (w <= 0.0001 || (aSegMeta.z <= 0.001 && aSegMeta.w <= 0.001)) {\n    gl_Position = vec4(2.0, 2.0, 2.0, 1.0);\n    return;\n  }\n\n  float u = clamp(position.x + 0.5, 0.0, 1.0);\n  float spanT = mix(aSegA.w, aSegB.w, u);\n  vUv = vec2(mix(0.76, 0.24, spanT), position.y + 0.5);\n  vec3 c0 = unpackRgb24(aSegMeta.x);\n  vec3 c1 = unpackRgb24(aSegExtra.x);\n  vColor = mix(c0, c1, smoothstep(0.04, 0.32, spanT));\n  vAlpha = mix(aSegMeta.z, aSegMeta.w, u);\n  vHdr = aSegExtra.w;\n  vUvRect = aSegUvRect;\n\n  vec3 a = aSegA.xyz;\n  vec3 b = aSegB.xyz;\n  vec3 seg = b - a;\n  float len = length(seg);\n  if (len <= 0.0001) {\n    gl_Position = vec4(2.0, 2.0, 2.0, 1.0);\n    return;\n  }\n  float wScale = mix(aSegExtra.y, aSegExtra.z, u);\n  if (uIs2D > 0.5) {\n    vec3 dir = seg / len;\n    vec3 side = vec3(-dir.y, dir.x, 0.0);\n    vec3 worldPos = mix(a, b, u) + side * (position.y * w * wScale);\n    gl_Position = projectionMatrix * modelViewMatrix * vec4(worldPos, 1.0);\n  } else {\n    vec4 mvA = modelViewMatrix * vec4(a, 1.0);\n    vec4 mvB = modelViewMatrix * vec4(b, 1.0);\n    vec2 vdir = mvB.xy - mvA.xy;\n    float vlen = length(vdir);\n    vec2 vside = vlen > 0.0001 ? (vec2(-vdir.y, vdir.x) / vlen) : vec2(1.0, 0.0);\n    vec4 mvPos = mix(mvA, mvB, u);\n    float worldW = w * wScale;\n    float tipKeep = smoothstep(0.001, 0.012, w);\n    float minScreenW = abs(mvPos.z) * 0.0038 * max(0.16, 1.0 - spanT * 0.84) * tipKeep;\n    mvPos.xy += vside * (position.y * max(worldW, minScreenW));\n    gl_Position = projectionMatrix * mvPos;\n  }\n}\n";
export const RIBBON_FRAGMENT_GLSL: "\nprecision highp float;\n\nuniform sampler2D uTrailTex;\nuniform float uHasTrailTex;\nuniform float uTrailFlipV;\nuniform vec4 uTrailUvRect;\nuniform sampler2D uSoftDepthTex;\nuniform float uHasSoftDepth;\nuniform float uSoftFade;\nuniform vec2 uInvViewport;\nuniform vec2 uCamNearFar;\nuniform vec4 uCustom1;\nuniform vec4 uCustom2;\n\nvarying vec2 vUv;\nvarying vec3 vColor;\nvarying float vAlpha;\nvarying float vHdr;\nvarying vec4 vUvRect;\n\n\nfloat vfxLinearizeDepth(float zNdc, vec2 camNearFar) {\n  float z = zNdc * 2.0 - 1.0;\n  float n = camNearFar.x;\n  float f = camNearFar.y;\n  return (2.0 * n * f) / max(0.0001, f + n - z * (f - n));\n}\n\nfloat vfxComputeSoftFade(\n  sampler2D depthTex,\n  float hasDepth,\n  vec2 fragCoord,\n  vec2 invViewport,\n  vec2 camNearFar,\n  float fragDepthZ,\n  float softFade\n) {\n  if (hasDepth < 0.5 || softFade <= 0.0001) return 1.0;\n  float sceneDepthRaw = texture2D(depthTex, fragCoord * invViewport).r;\n  float sceneZ = vfxLinearizeDepth(sceneDepthRaw, camNearFar);\n  float partZ = vfxLinearizeDepth(fragDepthZ, camNearFar);\n  return clamp((sceneZ - partZ) / max(0.0001, softFade), 0.0, 1.0);\n}\n\nvec4 vfxChannelPicker(vec4 rgba, vec4 mask) {\n  return rgba * mask;\n}\n\nfloat vfxChannelPickerAdd(vec4 rgba, vec4 mask) {\n  return clamp(dot(rgba, mask), 0.0, 1.0);\n}\n\nfloat vfxChannelPickerClamped(vec4 rgba, vec4 mask) {\n  return clamp(dot(clamp(rgba * mask, 0.0, 1.0), vec4(1.0)), 0.0, 1.0);\n}\n\nvec3 vfxDesaturate(vec3 rgb, float amt) {\n  const vec3 lumaW = vec3(0.2126729, 0.7151522, 0.0721750);\n  float luma = dot(rgb, lumaW);\n  return mix(rgb, vec3(luma), clamp(amt, 0.0, 1.0));\n}\n\nfloat vfxSafeSmoothstep(float e0, float e1, float x) {\n  float d = e1 - e0;\n  float sd = abs(d) < 1e-5 ? (d < 0.0 ? -1e-5 : 1e-5) : d;\n  float t = clamp((x - e0) / sd, 0.0, 1.0);\n  return t * t * (3.0 - 2.0 * t);\n}\n\nbool vfxHasFlag(float flags, float bitVal) {\n  return mod(floor(flags / bitVal + 0.001), 2.0) > 0.5;\n}\n\nvec2 vfxPolarCoords(vec2 uv, vec2 center) {\n  vec2 d = uv - center;\n  float r = length(d) * 2.0;\n  float ang = atan(d.y, d.x) * 0.15915494309 + 0.5;\n  return vec2(r, ang);\n}\n\nvec4 vfxSampleAtlasRectWrapped(sampler2D atlasTex, vec4 rect, vec2 uv, float flipV, bool clampU, bool clampV) {\n  vec2 tiled = vec2(\n    clampU ? clamp(uv.x, 0.001, 0.999) : fract(uv.x),\n    clampV ? clamp(uv.y, 0.001, 0.999) : fract(uv.y)\n  );\n  vec2 mapped = vec2(\n    mix(rect.x, rect.z, tiled.x),\n    mix(rect.y, rect.w, tiled.y)\n  );\n  if (flipV > 0.5) mapped.y = 1.0 - mapped.y;\n  return texture2D(atlasTex, mapped);\n}\n\nvec4 vfxSampleAtlasRect(sampler2D atlasTex, vec4 rect, vec2 uv, float flipV) {\n  return vfxSampleAtlasRectWrapped(atlasTex, rect, uv, flipV, false, false);\n}\n\n\nvec2 vfxFlipbookGrid(vec2 tiles) {\n  return max(vec2(1.0), floor(tiles + 0.5));\n}\n\nfloat vfxFlipbookFramePosition(float lifeRatio, vec2 grid, float cycles) {\n  float total = grid.x * grid.y;\n  cycles = max(0.01, cycles);\n  float phase = lifeRatio * cycles;\n  if (phase >= 1.0 && cycles <= 1.001) return total - 0.001;\n  return min(fract(phase), 0.9999) * total;\n}\n\nvec2 vfxFlipbookFrameUv(float frameIndex, vec2 localUv, vec2 grid) {\n  vec2 cell = vec2(mod(frameIndex, grid.x), floor(frameIndex / grid.x));\n  return (cell + localUv) / grid;\n}\n\n\n// Splits uv0 into flipbook cell coordinates (supports top-down grid + rowMode random/custom).\n// Returns (uvA, uvB) packed in vec4; meta.z = frame index, meta.w = next-frame blend.\nvec4 vfxComputeFlipbookUvPair(vec2 uv0, vec4 flipbookGridInfo, float frameIndex) {\n  vec2 grid = max(vec2(1.0), floor(flipbookGridInfo.xy + 0.5));\n  if (grid.x <= 1.0 && grid.y <= 1.0) {\n    return vec4(uv0, uv0);\n  }\n  float total = grid.x * grid.y;\n  float f0 = clamp(floor(frameIndex), 0.0, total - 1.0);\n  float f1 = min(f0 + 1.0, total - 1.0);\n  float col0 = mod(f0, grid.x);\n  float row0 = floor(f0 / grid.x);\n  float col1 = mod(f1, grid.x);\n  float row1 = floor(f1 / grid.x);\n  // Flip V inside cell so Unity top-left flipbook grid maps cleanly to OpenGL UV (bottom-up).\n  vec2 cellUvA = vec2((col0 + uv0.x) / grid.x, 1.0 - (row0 + 1.0 - uv0.y) / grid.y);\n  vec2 cellUvB = vec2((col1 + uv0.x) / grid.x, 1.0 - (row1 + 1.0 - uv0.y) / grid.y);\n  return vec4(cellUvA, cellUvB);\n}\n\nvec3 vfxEvalUberRamp(\n  vec3 satMain,\n  vec3 lastColor,\n  vec3 midColor,\n  vec3 whiteColor,\n  float midHigh,\n  float midLow\n) {\n  float denom = max(1e-5, abs(1.0 - midHigh)) * (1.0 - midHigh < 0.0 ? -1.0 : 1.0);\n  vec3 remappedHigh = clamp((satMain - vec3(midHigh)) / denom, 0.0, 1.0);\n  vec3 remappedLow = clamp((satMain * (remappedHigh - vec3(midLow))) / denom, 0.0, 1.0);\n  vec3 lo = mix(lastColor, midColor, remappedLow);\n  vec3 hi = mix(midColor, whiteColor, remappedHigh);\n  return mix(lo, hi, clamp(satMain, 0.0, 1.0));\n}\n\n\nvoid main() {\n  float alpha = vAlpha;\n  vec3 col = vColor;\n  vec4 uvRect = (vUvRect.z > vUvRect.x && vUvRect.w > vUvRect.y) ? vUvRect : uTrailUvRect;\n  if (uHasTrailTex > 0.5 && uvRect.z > uvRect.x && uvRect.w > uvRect.y) {\n    float localV = mix(0.08, 0.92, 1.0 - vUv.y);\n    vec2 mapped = vec2(\n      mix(uvRect.x, uvRect.z, clamp(vUv.x, 0.0, 1.0)),\n      mix(uvRect.y, uvRect.w, localV)\n    );\n    if (uTrailFlipV > 0.5) mapped.y = 1.0 - mapped.y;\n    vec4 texCol = texture2D(uTrailTex, mapped);\n    alpha *= texCol.a;\n    col *= texCol.rgb;\n  } else {\n    float d = abs(vUv.y - 0.5) * 2.0;\n    float edge = 1.0 - smoothstep(0.25, 1.0, d);\n    alpha *= edge;\n    col = mix(col, vec3(1.0), edge * 0.35);\n  }\n  float soft = vfxComputeSoftFade(uSoftDepthTex, uHasSoftDepth, gl_FragCoord.xy, uInvViewport, uCamNearFar, gl_FragCoord.z, uSoftFade);\n  alpha *= soft;\n  if (alpha < 0.01) discard;\n  gl_FragColor = vec4(col * max(0.0, vHdr) * max(0.0, uCustom1.x + 1.0), alpha);\n}\n";
